const token = 'nc_pat_Ze1MtFuNyhWwbvWludXs0U4K4_8_pHjv96Xh-8OL';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://base.e-metalabs.com/api/v3/data/pch2k3ljr1ut4if/mkdvw5qxol1nuf1/records',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
  });

  const records = Array.isArray(response) ? response : response?.records;

  if (!Array.isArray(records)) {
    throw new Error('La réponse NocoDB ne contient pas de tableau records.');
  }

  const latestRecord = [...records]
    .sort((a, b) => b.id - a.id)
    .slice(0, 1);

  return latestRecord.map(record => ({ json: record }));
} catch (error) {
  console.error('Erreur lors de la récupération des enregistrements NocoDB :', error);
  throw error;
}

return [{
