const text = $input.first().json.text || "";
let score = 100;
let reasons = [];

// Critère 1 : Longueur minimale pour un mémorandum de direction (min 800 caractères)
if (text.length < 800) {
  score -= 30;
  reasons.push("Livrable trop court");
}

// Critère 2 : Présence de la signature institutionnelle
if (!text.includes("e-META LABS")) {
  score -= 20;
  reasons.push("Signature e-META LABS absente");
}

// Critère 3 : Structure formelle minimale
const requiredSections = ["MÉMORANDUM", "OBJET", "RECOMMANDATION"];
const missingSections = requiredSections.filter(sec => !text.toUpperCase().includes(sec));
if (missingSections.length > 0) {
  score -= (missingSections.length * 15);
  reasons.push(`Sections manquantes: ${missingSections.join(', ')}`);
}

// Statut d'arbitrage
const status = (score >= 80) ? "APPROVED" : "MANUAL_REVIEW_REQUIRED";

return [{
  json: {
    text: text,
    qualityScore: score,
    validationStatus: status,
    auditNotes: reasons.length ? reasons.join(" | ") : "Conforme aux standards exécutifs"
  }
}];

const records = $input.first().json.list || [];
const today = new Date().toISOString().split('T')[0]; // Format YYYY-MM-DD

let totalGenerated = 0;
let autoAnchored = 0;
let humanReviewed = 0;

records.forEach(record => {
  // Supposons que le champ de date s'appelle "CreatedAt" ou "created_at"
  const recordDate = record.CreatedAt ? record.CreatedAt.split('T')[0] : '';

  if (recordDate === today) {
    totalGenerated++;
    // Si le statut ou une métadonnée indique un ancrage automatique ou une révision
    if (record.status === "success") {
      autoAnchored++;
    } else {
      humanReviewed++;
    }
  }
});

return [{
  json: {
    date: today,
    total: totalGenerated,
    anchored: autoAnchored,
    review: humanReviewed
  }
}];

const rawHtml = $input.first().json.data || "";
// Nettoyage basique des balises HTML et des espaces superflus
const cleanText = rawHtml.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();

// On extrait un résumé ou les 2000 premiers caractères pertinents
const contextualData = cleanText.substring(0, 2500);

