const contextSnippets = points.map((p, i) => {
  const payload = p.payload || {};
  return `--- ARCHIVE OFFICIELLE #${i + 1} (Pertinence: ${Math.round(p.score * 100)}%) ---\n` +
         `Secteur: ${payload.secteur || 'Général'}\n` +
         `Contenu probant: ${payload.pageContent || payload.content || JSON.stringify(payload)}`;
}).join('\n\n');

